using System;using System.IO;using System.Linq;using System.Net;using System.Net.Sockets;using System.Threading;using System.Threading.Tasks;using System.Diagnostics;using System.Collections.Generic;using System.Reflection;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Threading;using System.Web.Script.Serialization;
class NetworkReminderTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 [DllImport("user32.dll")]static extern bool OpenClipboard(IntPtr h);[DllImport("user32.dll")]static extern bool CloseClipboard();
 static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var child in Tree(VisualTreeHelper.GetChild(o,i)))yield return child;}
 static void Pump(){var f=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};timer.Tick+=(s,e)=>{timer.Stop();f.Continue=false;};timer.Start();Dispatcher.PushFrame(f);}
 static void Wait(Task t){var until=DateTime.UtcNow.AddSeconds(5);while(!t.IsCompleted&&DateTime.UtcNow<until)Pump();if(!t.IsCompleted)throw new Exception("Test task timeout");t.GetAwaiter().GetResult();}
 static ProxyProbe Reading(string kind,DateTime when){return new ProxyProbe{Kind=kind,CheckedUtc=when,Channel="manual|http://127.0.0.1:7890"};}
 [STAThread]static int Main(string[] args){if(args.Contains("--hold-clipboard")){for(int i=0;i<200;i++){if(OpenClipboard(IntPtr.Zero)){Console.WriteLine("LOCKED");Console.Out.Flush();Thread.Sleep(2500);CloseClipboard();return 0;}Thread.Sleep(10);}return 3;}
 Environment.SetEnvironmentVariable("CONAN_PET_TEST_MODE","1");Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());AssistantWindow window=null;TerminalWindow terminal=null;AssistantRuntime runtime=null;
 try{var now=DateTime.UtcNow;var cfg=new MonitorConfig{ExitLookupEnabled=true,ProxyTimeoutAlerts=true,ExitProxyMode="manual",ExitProxyAddress="http://127.0.0.1:7890"};var health=new ProxyHealthMonitor();Check(health.Observe(Reading("timeout",now),cfg,now)==null,"one transient timeout does not notify");var notice=health.Observe(Reading("timeout",now.AddSeconds(60)),cfg,now.AddSeconds(60));Check(notice!=null&&notice.Key.StartsWith("monitor:proxy:")&&notice.Text.Contains("超时"),"two consecutive proxy timeouts produce a warning");Check(health.Observe(Reading("timeout",now.AddSeconds(61)),cfg,now.AddSeconds(61))==null,"persistent failure respects reminder cooldown");Check(health.Observe(Reading("timeout",now.AddSeconds(361)),cfg,now.AddSeconds(361))!=null,"persistent outage can remind again after cooldown");Check(health.Observe(Reading("ok",now.AddSeconds(362)),cfg,now.AddSeconds(362))==null&&health.Status.Contains("通过"),"successful check resets consecutive failure streak");Check(health.Observe(Reading("timeout",now.AddSeconds(363)),cfg,now.AddSeconds(363))==null,"recovery requires new consecutive failures");cfg.ProxyTimeoutAlerts=false;Check(health.Observe(Reading("timeout",now.AddSeconds(364)),cfg,now.AddSeconds(364))==null,"proxy alert switch disables warnings");cfg.ProxyTimeoutAlerts=true;cfg.ExitLookupEnabled=false;Check(health.Observe(Reading("timeout",now.AddSeconds(365)),cfg,now.AddSeconds(365))==null,"disabled outbound lookup prevents alerts");cfg.ExitLookupEnabled=true;health=new ProxyHealthMonitor();health.Observe(Reading("timeout",now),cfg,now);health.Observe(Reading("service-error",now.AddSeconds(1)),cfg,now.AddSeconds(1));Check(health.Observe(Reading("timeout",now.AddSeconds(2)),cfg,now.AddSeconds(2))==null,"service failures are not counted as consecutive proxy timeouts");Check(health.Observe(Reading("bypassed",now.AddSeconds(3)),cfg,now.AddSeconds(3))==null&&health.Status.Contains("未使用"),"direct traffic is not reported as a healthy proxy");Check(health.Observe(Reading("timeout",now.AddSeconds(-1)),cfg,now)==null,"old probe cannot produce new warnings");var foreign=Reading("timeout",now.AddSeconds(4));foreign.Channel="manual|http://127.0.0.1:9999";Check(health.Observe(foreign,cfg,foreign.CheckedUtc)==null,"late result from previous proxy settings discarded");Check(ProxyHealthMonitor.Probe("direct","").Kind=="bypassed","direct probe does not query external service");
 Check(ProxyHealthMonitor.IsTimeout(new IOException("read failed",new SocketException(10060))),"body read timeout is recognized through nested socket error");Check(!ProxyHealthMonitor.IsTimeout(new InvalidDataException("bad response")),"malformed response is not mislabeled timeout");var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();bool accepted=false;var hold=Task.Run(()=>{try{using(var peer=listener.AcceptTcpClient()){accepted=true;Thread.Sleep(9500);}}catch(SocketException){}finally{listener.Stop();}});int port=((IPEndPoint)listener.LocalEndpoint).Port;var actual=ProxyHealthMonitor.Probe("manual","http://127.0.0.1:"+port);Check(accepted&&actual.Kind=="timeout","real local proxy withholding response produces timeout without forwarding traffic");listener.Stop();
 int writes=0;var copied=ClipboardCopy.WriteText("198.51.100.4",text=>{writes++;if(writes<2)throw new COMException("busy",unchecked((int)0x800401D0));});Wait(copied);Check(copied.Result&&writes==2,"clipboard contention retries then succeeds");writes=0;var blocked=ClipboardCopy.WriteText("198.51.100.4",text=>{writes++;throw new COMException("busy",unchecked((int)0x800401D0));});Wait(blocked);Check(!blocked.Result&&writes==4,"persistent clipboard contention returns failure without throwing");var empty=ClipboardCopy.WriteText("",text=>{throw new Exception("must not write");});Wait(empty);Check(!empty.Result,"empty IP does not replace clipboard");
 string folder=Path.Combine(args[0],"user-data-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);runtime=new AssistantRuntime(folder);runtime.Config.Monitor.Quota.Enabled=false;window=new AssistantWindow(runtime,folder);window.Show();var tabs=(TabControl)typeof(AssistantWindow).GetField("tabs",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(window);tabs.SelectedIndex=1;Pump();typeof(AssistantWindow).GetField("snapshot",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(window,new AssistantSnapshot{IPText="198.51.100.4"});using(var process=Process.Start(new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"--hold-clipboard"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true})){var ready=process.StandardOutput.ReadLineAsync();Check(ready.Wait(4000)&&ready.Result=="LOCKED","isolated process holds clipboard without changing contents");var button=Tree(window).OfType<Button>().First(b=>Convert.ToString(b.Content)=="复制IP地址");button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var until=DateTime.UtcNow.AddSeconds(2);while(!button.IsEnabled&&DateTime.UtcNow<until)Pump();var status=(TextBlock)typeof(AssistantWindow).GetField("copyIpStatus",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(window);Check(window.IsVisible&&button.IsEnabled&&status.Text.Contains("占用"),"real copy-IP button survives actual Windows clipboard lock and shows retry message");process.WaitForExit(4000);}
 terminal=new TerminalWindow(runtime,new SkillRuntime(folder),new AdvancedRuntime(folder),folder,x=>{},()=>{},x=>{},()=>"free");terminal.Show();terminal.ShowProxyPage();Pump();Check(Tree(terminal).OfType<CheckBox>().Any(b=>Convert.ToString(b.Content)=="代理超时或无法连接时提醒"),"proxy reminder controls present in unified memo");var cooldown=Tree(terminal).OfType<TextBox>().First(b=>System.Windows.Automation.AutomationProperties.GetName(b)=="重复提醒间隔（秒）");cooldown.Text="120";Tree(terminal).OfType<Button>().First(b=>Convert.ToString(b.Content)=="保存代理提醒设置").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var saved=new JavaScriptSerializer().Deserialize<AssistantConfig>(File.ReadAllText(Path.Combine(folder,"assistant.json")));Check(saved.Monitor.ProxyCooldownSeconds==120,"proxy reminder options persist from native page");
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(terminal!=null)terminal.Close();if(window!=null)window.Close();if(runtime!=null)runtime.Telemetry.Dispose();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"network-reminder-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,external_proxy_traffic_forwarded=false,real_user_settings_changed=false,clipboard_contents_changed=false}));return failures==0?0:1;}
}
